COMMON_SOURCES=("src.book.petrov-database-internals.1e","src.book.silberschatz-database-system-concepts.7e","src.manual.postgresql-17.10","src.book.rogov-postgresql-14-internals")

LESSONS=(
Lesson(140,"Lesson_140-locking-two-phase-locking-and-deadlock-detection","Locking, two-phase locking and deadlock detection","28-locking-two-phase-locking-and-deadlock-detection.md","wiki.database.locking-2pl-deadlock","Làm thế nào phân biệt lock wait hợp lệ với deadlock, truy wait-for graph và retry mà không nhân đôi tác dụng?",COMMON_SOURCES,("SRC-PETROV-DATABASE-INTERNALS-1E","SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E","SRC-POSTGRESQL-17-10-MANUAL","SRC-ROGOV-POSTGRESQL-14-INTERNALS"),(
("Khoá bảo vệ điều gì","Lock manager điều phối quyền truy cập lên resource: relation, page, tuple, transaction ID hoặc advisory key. Shared/exclusive chỉ là mô hình tối giản; PostgreSQL có nhiều table- và row-lock modes với ma trận xung đột riêng. Lock được cấp không đồng nghĩa statement đã hoàn thành: session có thể giữ lock đến cuối transaction. Vì vậy phải quan sát holder, waiter, resource, mode, transaction age và query state cùng lúc."),
("Two-phase locking và strictness","Trong 2PL, growing phase chỉ lấy lock; sau lần nhả đầu tiên là shrinking phase và không lấy thêm. Quy tắc này cho conflict-serializability nhưng không tự nói recoverability. Strict 2PL giữ exclusive locks đến commit/abort, ngăn transaction khác đọc/ghi dữ liệu chưa commit và đơn giản hoá recovery. PostgreSQL MVCC không thể được mô tả như một strict-2PL engine thuần; row versions xử lý reads, locks vẫn điều phối write conflicts và DDL."),
("Chờ không phải deadlock","Một lock wait có cạnh T2→T1 nhưng chưa có cycle; nếu T1 tiến tới commit thì hệ tự thông. Deadlock có cycle trong wait-for graph, chẳng hạn T1 giữ A chờ B còn T2 giữ B chờ A. Thêm session thứ ba hoặc nhiều resource tạo cycle dài hơn. Chẩn đoán phải dựng cạnh từ waiter tới blocker thay vì chỉ liệt kê những session có trạng thái chờ."),
("Phát hiện và chọn nạn nhân","Engine có thể chạy detector sau deadlock timeout, tìm cycle rồi abort một participant để phá vòng. Nạn nhân không phải transaction có lỗi nghiệp vụ; đó là quyết định recovery của engine. PostgreSQL báo deadlock detected và rollback transaction hiện tại. Ứng dụng phải coi deadlock/serialization failure là transient, rollback toàn attempt, lấy state mới và retry có giới hạn."),
("Phòng ngừa và vận hành","Quy tắc thứ tự lock nhất quán loại cycle nếu mọi code path tuân thủ. Transaction ngắn, không chờ input/network trong transaction, index đúng để giảm số row bị chạm, batch có giới hạn và lock timeout giúp giảm blast radius. Kill backend hoặc restart database chỉ là biện pháp khẩn cấp có mất work; không thay root-cause analysis."),
("Retry an toàn","Retry nguyên logical transaction, không retry riêng statement sau khi transaction đã failed. Operation ID/idempotency key ngăn duplicate side effects; exponential backoff có jitter tránh herd. Log attempt, SQLSTATE, blocking PID, lock target, elapsed time và final outcome. Nếu transaction gọi HTTP/email trước commit, retry có thể lặp tác dụng; cần outbox hoặc compensation."),
),(
"Hai transaction update hai account theo thứ tự đảo ngược tạo cycle hai cạnh","Một transaction giữ row lock rồi sleep tạo lock wait nhưng không tạo cycle","Query thiếu index khoá nhiều row hơn dự kiến và làm tăng waiter count","DDL lấy table lock xung đột với transaction đọc/ghi dài","deadlock_timeout thấp làm detector/log hoạt động dày nhưng không chữa thứ tự lock","lock_timeout huỷ statement vì chờ lâu dù không có deadlock","statement_timeout và lock_timeout tạo failure semantics khác nhau","SELECT FOR UPDATE biến read thành locking read có phạm vi theo rows thực sự khoá","SKIP LOCKED phù hợp work queue nhưng có thể tạo starvation/fairness trade-off","NOWAIT fail-fast và chuyển quyền quyết định sang caller","advisory lock không được engine gắn với row invariant","connection mất sau commit tạo outcome ambiguity ngoài deadlock","retry không có idempotency key có thể nhân đôi external effect","monitor chỉ active sessions bỏ sót idle in transaction holder","restart xoá triệu chứng nhưng mất evidence về blocker chain")),
Lesson(141,"Lesson_141-mvcc-snapshots-and-vacuum","MVCC, snapshots and vacuum","29-mvcc-snapshots-and-vacuum.md","wiki.database.mvcc-snapshots-vacuum","Row version được nhìn thấy theo snapshot nào, vì sao dead tuple tồn tại, và long transaction gây bloat/wraparound risk ra sao?",COMMON_SOURCES,("SRC-PETROV-DATABASE-INTERNALS-1E","SRC-POSTGRESQL-17-10-MANUAL","SRC-ROGOV-POSTGRESQL-14-INTERNALS","SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E"),(
("MVCC là visibility protocol","MVCC giữ nhiều row versions và chọn version visible theo transaction/snapshot metadata. Nó giảm read-write blocking nhưng không xoá write-write coordination, schema locks hay predicate conflicts. PostgreSQL tuple header chứa transaction identity/status-related metadata; visibility còn phụ thuộc snapshot và commit state. Nói 'reader không block writer' chỉ đúng với ordinary data reads trong ranh giới documented, không phải mọi lock loại nào."),
("Snapshot không phải một khái niệm duy nhất","Ở PostgreSQL Read Committed, mỗi statement lấy snapshot mới; hai SELECT trong cùng transaction có thể thấy commits khác nhau. Repeatable Read và Serializable dùng transaction-level view phù hợp với mode. Snapshot xác định tập transaction được coi là visible/in-progress, không phải copy vật lý toàn database. Một cursor, function hoặc command có thêm chi tiết cần kiểm manual."),
("Update tạo version mới","UPDATE thường tạo tuple version mới và version cũ trở thành dead khi không snapshot nào còn cần. DELETE cũng để lại dead tuple cho tới vacuum. HOT có thể tránh index entries mới khi điều kiện thoả, nhưng không biến cleanup thành miễn phí. Dead tuples làm tăng heap/index work, buffer pressure và storage; bloat là phần không tái sử dụng hiệu quả, không đồng nhất một counter duy nhất."),
("Vacuum làm gì và không làm gì","Routine VACUUM nhận diện tuples đã chết theo horizon, đánh dấu space tái sử dụng, dọn index theo phase, cập nhật visibility map và có vai trò chống transaction-ID wraparound. Nó thường không trả file về OS. VACUUM FULL rewrite/lock mạnh, không phải nút dọn định kỳ. ANALYZE và VACUUM liên quan vận hành nhưng mục tiêu khác."),
("Horizon và long transaction","Snapshot/transaction cũ có thể giữ global xmin/horizon thấp khiến versions mới chết vẫn chưa removable. Idle in transaction đặc biệt nguy hiểm vì không làm việc nhưng giữ snapshot/locks. Replication slot, prepared transaction và standby feedback cũng có thể giữ WAL hoặc cleanup horizon. Vì vậy chỉ nhìn table bytes không đủ xác định nguyên nhân."),
("Đo và xử lý","Theo dõi transaction age, idle-in-transaction duration, dead tuples, autovacuum last run/progress, table/index size, transaction ID age và replication-slot/WAL retention. Điều tra workload/churn và threshold trước khi tune. Kết thúc blocker phải theo runbook và owner; sau cleanup, space có thể chỉ tái sử dụng nội bộ nên 'file không nhỏ' không chứng minh vacuum thất bại."),
),(
"Read Committed lấy snapshot theo statement và cho kết quả khác nhau giữa hai SELECT","Repeatable Read giữ view ổn định nhưng transaction update có thể bị abort","long idle transaction giữ horizon dù CPU gần bằng không","UPDATE cùng row nhiều lần sinh chain version và HOT phụ thuộc index columns/page space","DELETE không trả ngay heap space về filesystem","routine VACUUM cho phép reuse nhưng thường không shrink file","VACUUM FULL rewrite và cần lock mạnh nên không chạy phản xạ trên production","autovacuum threshold kết hợp base threshold và scale factor theo version/config","dead-tuple estimate là estimate và có độ trễ","visibility map hỗ trợ index-only scan nhưng bit có thể bị clear bởi write","freeze bảo vệ transaction ID wraparound và khác cleanup thông thường","replication slot có thể giữ WAL; standby feedback có thể trì hoãn cleanup","bloat cần đo heap và index riêng, không suy từ dead tuple duy nhất","long transaction alert cần age và owner/query context","sau khi blocker kết thúc cần quan sát vacuum progress thay vì tuyên bố tự phục hồi")),
Lesson(142,"Lesson_142-isolation-levels-chosen-by-anomaly-not-by-name","Isolation levels chosen by anomaly, not by name","30-isolation-levels-by-anomaly.md","wiki.database.isolation-levels-anomalies","Chọn isolation/locking theo invariant và anomaly cụ thể như thế nào thay vì tin tên mức cô lập?",COMMON_SOURCES+("src.book.kleppmann-ddia.1e",),("SRC-PETROV-DATABASE-INTERNALS-1E","SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E","SRC-POSTGRESQL-17-10-MANUAL","SRC-ROGOV-POSTGRESQL-14-INTERNALS","SRC-KLEPPMANN-DDIA-1E"),(
("Bắt đầu từ invariant","Isolation level là phương tiện. Trước hết viết invariant bằng predicate có thể kiểm, chỉ ra rows/ranges tham gia và schedule cạnh tranh. 'Không âm', 'còn ít nhất một bác sĩ trực' và 'một username duy nhất' có conflict shapes khác nhau. Nếu invariant đã là unique/check/foreign-key constraint thì ưu tiên engine enforcement; nếu predicate nhiều rows, cần serializable, explicit locking hoặc materialize conflict."),
("Các anomaly đọc","Dirty read đọc uncommitted data; nonrepeatable read thấy cùng row đổi sau commit khác; phantom thấy tập rows thoả predicate đổi. Đây là phenomena chuẩn nhưng không bao phủ mọi anomaly. PostgreSQL không thực thi Read Uncommitted riêng mà ánh xạ thành Read Committed; PostgreSQL Repeatable Read mạnh hơn minimum standard về phantom nhưng vẫn có serialization anomaly."),
("Lost update và write skew","Lost update xảy ra khi read-modify-write cạnh tranh làm một update che update kia. Atomic UPDATE hoặc row lock/compare-and-set có thể chặn theo case. Write skew xảy ra khi hai transaction đọc cùng predicate rồi ghi hai rows khác nhau; first-committer-wins trên cùng row không bắt được. Snapshot isolation do đó không đồng nghĩa serializable."),
("PostgreSQL theo từng mức","Read Committed snapshot theo statement và statement update có recheck/wait behavior. Repeatable Read cung cấp snapshot ổn định, ngăn dirty/nonrepeatable/phantom theo implementation nhưng có thể abort khi row đổi và vẫn cho write skew. Serializable dùng Serializable Snapshot Isolation, theo dõi dangerous structures/predicate dependencies và abort để bảo đảm serializable execution."),
("Ba cách chặn predicate anomaly","Một là chạy Serializable và retry serialization failures. Hai là explicit lock tất cả rows đại diện predicate, nhưng phải bảo đảm rows tồn tại và query/index thực sự bao phủ conflict; nonexistence khó khoá. Ba là materialize invariant thành một row/constraint/counter để concurrent changes cùng conflict. Mỗi cách có contention, complexity và correctness proof khác nhau."),
("Kiểm bằng schedule","Concurrency test phải có barrier: T1 đọc, T2 đọc, mỗi bên ghi, rồi commit theo thứ tự kiểm soát. Chạy tuần tự không kiểm isolation. Ghi result, SQLSTATE, committed set và invariant cuối. Abort có thể là kết quả đúng. So DBMS/version bằng evidence riêng vì cùng label không đảm bảo implementation details giống nhau."),
),(
"dirty read cần giá trị chưa commit chứ không chỉ giá trị cũ","nonrepeatable read cùng row khác phantom trên predicate set","lost update có thể tránh bằng atomic increment mà không tăng toàn transaction lên serializable","write skew của hai bác sĩ ghi hai rows khác nhau vượt qua row-level conflict","PostgreSQL Read Uncommitted hành xử như Read Committed","Read Committed có snapshot theo command không theo transaction","PostgreSQL Repeatable Read không có phantom theo bảng manual nhưng vẫn có serialization anomaly","Serializable có thể abort transaction hợp lệ cục bộ để giữ global serial order","retry phải chạy lại toàn decision từ snapshot mới","SELECT FOR UPDATE chỉ khoá rows tìm thấy và không luôn bảo vệ absence","unique constraint là enforcement tốt hơn application pre-check cho uniqueness","predicate lock trong SSI không đồng nghĩa blocking row lock","read-only serializable deferrable có semantics tối ưu riêng","test không có barrier cho kết quả không tái hiện được","isolation choice phải ghi invariant, anomaly, mechanism và retry contract")),
Lesson(143,"Lesson_143-replication-lag-failover-and-split-brain","Replication, lag, failover and split brain","31-replication-lag-failover-and-split-brain.md","wiki.database.replication-lag-failover","Replication acknowledgment, lag, promotion và fencing ghép thành RPO/RTO có thể kiểm như thế nào?",("src.book.kleppmann-ddia.1e","src.manual.postgresql-17.10","src.book.rogov-postgresql-14-internals","src.book.silberschatz-database-system-concepts.7e"),("SRC-KLEPPMANN-DDIA-1E","SRC-POSTGRESQL-17-10-MANUAL","SRC-ROGOV-POSTGRESQL-14-INTERNALS","SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E"),(
("Replication có nhiều mục tiêu","Replica có thể phục vụ availability, read scaling, disaster recovery hoặc data distribution; một topology không tối ưu đồng thời mọi mục tiêu. Physical streaming phát WAL/block-level changes và giữ cluster gần giống primary; logical replication phát changes theo logical identity, cho selective replication/version use cases nhưng có constraint/conflict semantics riêng. Replica không phải backup vì operator error có thể được nhân bản."),
("Acknowledgment boundary","Asynchronous replication cho primary ACK trước khi standby durable/apply, tạo cửa sổ mất acknowledged commits khi failover. Synchronous replication chờ theo synchronous_commit/synchronous_standby_names và mode remote_write/flush/apply tương ứng; không được rút gọn thành 'sync không mất dữ liệu'. Nó vẫn phụ thuộc số standby/quorum, storage, config reload, network partition và việc chọn candidate."),
("Lag là vector","Byte/LSN lag, send lag, write lag, flush lag, replay lag và wall-clock visibility trả lời câu hỏi khác nhau. Zero byte lag tại một thời điểm không chứng minh replica đủ an toàn nếu monitoring stale hoặc timeline khác. Read-after-write trên replica cần routing/session token/wait-until-LSN hoặc đọc primary; eventual catch-up không tạo guarantee tự động."),
("Failover là protocol","Phát hiện primary không phản hồi chưa chứng minh primary chết. Promotion chọn standby, tạo timeline mới, cập nhật routing và phải ngăn primary cũ nhận writes. Fencing bằng STONITH, lease/quorum hoặc control plane đáng tin ngăn split brain. Sau promotion cần reconcile clients, slots, WAL archive, old-primary rejoin và backup lineage."),
("RPO và RTO","RPO là lượng dữ liệu được phép mất theo điểm thời gian/operation set; RTO là thời gian dịch vụ khôi phục. Đo bằng operation-ID ledger: xác định ACKed IDs trước fault và IDs hiện diện sau failover. Chỉ đếm row có thể sai nếu retry/duplicate. RTO phải có mốc fault detection, decision, promotion, route convergence và application readiness."),
("Thiết kế game day","Chỉ chạy trên cluster cô lập. Xác nhận restore path, fencing và stop conditions trước fault injection. Tải ghi có operation IDs; capture primary/standby LSN cùng timestamps; kill/isolate primary theo kịch bản; promote; kiểm accepted writes, lost/duplicate IDs và stale reads. Không tuyên bố synchronous RPO=0 nếu chưa test đúng mode/failure class."),
),(
"async ACK trước remote durability tạo acknowledged-write loss window","synchronous remote_write khác remote_flush và remote_apply","một synchronous standby cấu hình nhưng không available có thể chặn commit hoặc làm mode thay đổi theo policy","replication lag bytes khác replay time lag","read-after-write trên follower có thể thất bại dù primary commit thành công","monitoring connection up không chứng minh replay caught up","network partition tạo primary ambiguity và cần quorum/fencing","promotion không tự tắt old primary","split brain có thể tạo divergent timelines không merge tự động","logical replication không sao chép mọi DDL/sequence/large-object semantics như physical","replica truyền operator DELETE nên không thay point-in-time backup","WAL archive/slot retention có thể đầy disk khi consumer lag","RPO đo trên ACK ledger, không đo bằng cảm giác về sync/async","RTO gồm client/DNS/pool convergence chứ không chỉ promote command","rejoin old primary cần rewind/rebuild và kiểm timeline")),
Lesson(144,"Lesson_144-partitioning-against-sharding","Partitioning against sharding","32-partitioning-versus-sharding.md","wiki.database.partitioning-versus-sharding","Khi nào chia bảng trong một database đủ, khi nào phải shard qua nhiều node, và partition key được chứng minh bằng workload ra sao?",("src.book.kleppmann-ddia.1e","src.manual.postgresql-17.10","src.book.silberschatz-database-system-concepts.7e","src.book.petrov-database-internals.1e"),("SRC-KLEPPMANN-DDIA-1E","SRC-POSTGRESQL-17-10-MANUAL","SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E","SRC-PETROV-DATABASE-INTERNALS-1E"),(
("Hai ranh giới khác nhau","PostgreSQL declarative partitioning chia một logical table thành child partitions dưới một database/cluster; planner, catalog và transaction manager vẫn cùng hệ. Sharding phân data ownership qua nhiều nodes/databases và thêm routing, rebalance, distributed queries, cross-shard transactions, failure domains và topology metadata. Một số sản phẩm gọi shard là partition; phải nói physical/administrative boundary thay vì chỉ tin thuật ngữ."),
("Mục tiêu của partitioning","Partition pruning giảm partitions phải scan khi predicate cho phép suy ra partition key; maintenance có thể detach/drop partition theo thời gian; indexes/constraints được quản lý theo partition. Partitioning không tự làm query nhanh: quá nhiều partitions tăng planning/catalog overhead, pruning thất bại sẽ scan rộng, skew tạo hot partition. Phải đo bytes/pages/partitions touched và latency distribution."),
("Range, list và hash","Range phù hợp time/range access và lifecycle nhưng latest range có thể nóng. List hợp region/tenant categories hữu hạn nhưng default partition cần quản trị. Hash phân phối đều hơn theo key quality nhưng phá locality/range pruning và migration semantics. Composite/subpartitioning tăng option lẫn operational complexity; chỉ dùng khi workload evidence cần."),
("Chọn key từ workload","Liệt kê query shapes, ingest distribution, retention, joins, uniqueness và growth. Key tốt xuất hiện trong selective predicates/routing, phân phối load đủ đều, không đổi thường xuyên và tương thích lifecycle. Timestamp cho drop-by-month tốt nhưng không giúp point lookup nếu query không có time. Tenant ID route tốt nhưng tenant lớn tạo skew; có thể cần bucket/compound strategy."),
("Sharding thêm distributed systems","Router phải map key→shard theo versioned topology. Rebalance copy data trong khi writes tiếp diễn và cần cutover correctness. Cross-shard join/aggregation gây scatter-gather; global uniqueness và foreign key khó; multi-shard transaction cần coordination. Hot key vẫn nóng dù số shard tăng. Vì vậy shard sau khi chứng minh single-node/partitioned design không đạt capacity/SLO."),
("Quy trình quyết định","Trước hết sửa model/query/index, archive và partition theo lifecycle. Đo peak storage, write IOPS, CPU/memory, maintenance window và headroom. Nếu một failure/administrative domain không đủ hoặc capacity vượt scale-up hợp lý, thiết kế shard contract: key, router, replication per shard, rebalance, global ID, cross-shard policy và recovery. Quyết định phải có exit/rekey plan."),
),(
"partition pruning cần predicate có quan hệ suy ra được với partition key","partition key theo tháng hỗ trợ retention nhưng latest partition có thể hotspot","drop/detach partition khác DELETE từng row về WAL/lock/maintenance cost","quá nhiều partitions tăng planning/catalog overhead","local index trên partitions không tự tạo global uniqueness ngoài partition key","hash partitioning phân phối key space nhưng không đảm bảo workload đều nếu hot key","sharding đưa routing metadata thành consistency problem","scatter-gather latency bị quyết định bởi slow shard và fan-out","cross-shard transaction thêm coordinator/failure states","rebalance cần copy, catch-up, cutover và rollback evidence","tenant ID shard key gặp whale tenant skew","random key giảm locality và range scan efficiency","replication và sharding là hai trục: mỗi shard vẫn cần replicas","partitioning không thay index và không chữa query không sargable","chỉ shard sau capacity forecast, measured bottleneck và operational readiness")),
)

def fm(x:Lesson)->str:
    src='\n'.join(f'  - {s}' for s in x.sources)
    return f"---\nnote_id: {x.note_id}\nnote_type: concept-deep-dive\nstatus: review\nlanguage: vi\ncreated: 2026-10-01\nlast_verified: 2026-10-01\neditorial_pass: humanized-v1\nprimary_question: {x.question}\nsource_ids:\n{src}\naliases: [{x.title}]\ntags: [wiki/database-systems, postgresql, module-10]\nreference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}\n---\n"

def deep_note(x:Lesson)->str:
    parts=[fm(x),f"# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n"]
    for i,(h,b) in enumerate(x.core,1): parts.append(f"\n## {i}. {h}\n\n{b}\n")
    parts.append("\n## 7. Ma trận kiểm chứng từng mệnh đề\n\nMỗi mệnh đề dưới đây phải được kiểm bằng một schedule hoặc phép đo có điều kiện đầu vào rõ ràng. Không dùng một ảnh màn hình cuối làm bằng chứng thay cho lệnh, timestamp, cấu hình và raw output.\n")
    for i,p in enumerate(x.probes,1):
        parts.append(f"\n### 7.{i}. {p}\n\n**Giả thuyết.** {p}. **Cách kiểm.** Cố định phiên bản database, cấu hình, dữ liệu seed và thứ tự thao tác; ghi operation ID, transaction/session ID, thời điểm bắt đầu–kết thúc và trạng thái commit/abort. **Đối chứng.** Chạy một biến thể bỏ đúng yếu tố đang xét, không đổi đồng thời nhiều tham số. **Bằng chứng đạt.** Lưu command/script, raw result và counter trước–sau; giải thích cơ chế tạo ra quan sát. Một lần không tái hiện không đủ bác bỏ hiện tượng concurrency; cần barrier xác định và lặp có giới hạn.\n")
    parts.append("\n## 8. Khung chẩn đoán\n\n1. Viết hiện tượng quan sát được và mốc thời gian, không nhảy thẳng tới nguyên nhân.\n2. Ghi exact DBMS/version, topology, isolation/durability mode và workload.\n3. Dựng state hoặc dependency graph nhỏ nhất giải thích hiện tượng.\n4. Thu evidence ở cả client, engine và storage/replica nếu có.\n5. Nêu giả thuyết có dự đoán phân biệt được; đổi một biến và chạy lại.\n6. Phân biệt biện pháp giảm triệu chứng, sửa nguyên nhân và control ngăn tái diễn.\n7. Giữ failed run; không xoá evidence chỉ vì kết quả không như dự kiến.\n")
    parts.append("\n## 9. Câu hỏi tự kiểm tra\n\n1. Contract chính của cơ chế trong bài là gì và failure class nào nằm ngoài contract?\n2. Counter hoặc graph nào phân biệt symptom với root cause?\n3. Một phát biểu nào chỉ đúng cho PostgreSQL, không được khái quát thành SQL chung?\n4. Abort hoặc stale read khi nào là hành vi đúng theo cấu hình?\n5. Lab cần barrier, operation ID và đối chứng nào để tái hiện được?\n6. Biện pháp vận hành nào nguy hiểm nếu áp dụng trực tiếp lên production?\n")
    parts.append("\n## 10. Giới hạn và điều chưa cho phép kết luận\n\n- Chưa chạy lab database; mọi số đo phải được học viên tạo trong môi trường cô lập.\n- Hành vi theo version/dialect phải kiểm manual đúng hệ; note không thay runbook production.\n- Không suy benchmark, ngưỡng alert hay SLO phổ quát từ sách.\n- Không coi synchronous, serializable, vacuum hoặc partitioning là bảo đảm tuyệt đối ngoài cấu hình và failure model đã nêu.\n")
    refs='\n'.join(f"{i}. [[{s}]]" for i,s in enumerate(x.source_links,1))
    coverage='\n'.join(f"| [[{s}]] | Cơ chế, ranh giới và phản ví dụ liên quan đến bài | Đã đọc phạm vi có locator và diễn giải |" for s in x.source_links)
    parts.append(f"\n## Reference\n\n{refs}\n\n## Source coverage\n\n| Source slice | Nội dung sử dụng | Trạng thái |\n|---|---|---|\n{coverage}\n\n## Key takeaways\n\n- Bắt đầu từ invariant/failure model và bằng chứng, không bắt đầu từ tên tính năng.\n- Phân biệt contract chung với hành vi PostgreSQL cụ thể.\n- Concurrency và failover test phải có schedule, operation ID và raw output tái lập được.\n- Một control làm giảm rủi ro này có thể tăng latency, abort, coordination hoặc chi phí vận hành khác.\n- Chưa chạy lab thì trạng thái là tài liệu học thuật đã kiểm cấu trúc, không phải chứng nhận production.\n")
    return ''.join(parts)

def field(text,name):
    m=re.search(rf"(?m)^\*\*{re.escape(name)}\.\*\*\s*(.+)$",text)
    if not m: raise ValueError(f"missing {name}")
    return m.group(1).strip()

def section(text,heading):
    m=re.search(rf"(?ms)^## {re.escape(heading)}\n\n(.*?)(?=^## |\Z)",text)
    if not m: raise ValueError(f"missing section {heading}")
    return m.group(1).strip()

def contract(x):
    f=BASE/x.directory; n=(f/'note.md').read_text(); a=(f/'after-note.md').read_text()
    if '**Outcome.**' in n: return tuple(field(n,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
    return (field(section(n,'Mục tiêu bài học'),'Năng lực cần chứng minh'),field(section(a,'Tiêu chí hoàn thành'),'Cách đánh giá'),field(section(a,'Thực hành'),'Nhiệm vụ'),field(section(a,'Bài làm sau buổi học'),'Lỗi cần chủ động loại trừ'),field(section(a,'Bài làm sau buổi học'),'Nhiệm vụ'),field(section(n,'Mục tiêu bài học'),'Điều kiện hoàn thành'))

def curriculum(x,knowledge):
    outcome,assessment,lab,pitfalls,homework,done=contract(x)
    header=f"# Phase 4: SQL and Database Internals\n# Module 10: Storage Engine and Database Operations\n# Lesson {x.number}: {x.title}"
    body=re.sub(r'^---\n.*?\n---\n','',knowledge,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
    note=f"{header}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {outcome}\n\n**Điều kiện hoàn thành.** {done}\n\n{body}"
    safety="Chỉ thực hiện trên database/cluster thử nghiệm cô lập, có seed và đường khôi phục. Không giữ lock dài, ép vacuum, đổi isolation/durability, kill node, promote hay rebalance trên production. Lưu script, cấu hình, operation-ID ledger, raw counters và log; ảnh chụp không thay artifact tái chạy."
    qs='\n'.join(f"{i}. {q}" for i,q in enumerate(("Nêu contract và failure boundary của cơ chế.","Dựng schedule hoặc topology nhỏ nhất tái hiện lỗi.","Chọn ba chỉ số phân biệt triệu chứng với nguyên nhân.","Nêu một phát biểu chỉ đúng cho PostgreSQL và nguồn kiểm."),1))
    after=f"{header}\n\n## Thực hành\n\n**Nhiệm vụ.** {lab}\n\n{safety}\n\n## Kiểm tra cuối bài\n\n{qs}\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {assessment}\n\n**Điều kiện đạt.** {done}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {homework}\n\n**Lỗi cần chủ động loại trừ.** {pitfalls}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n"
    return note,after

def update_manifest(check=False):
    path=ROOT/'Docs/Second-Brain/second-brain-manifest.json'; data=json.loads(path.read_text())
    ids={x.note_id for x in LESSONS}
    registry=[n for n in data['note_registry'] if n.get('note_id') not in ids]
    for x in LESSONS:
        registry.append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-01'})
    tests=[t for t in data['retrieval_test_set'] if t.get('expected_note_id') not in ids]
    queries={
      140:['Cách phân biệt lock wait với deadlock cycle?','Vì sao deadlock victim phải retry toàn transaction?','Wait-for graph cần holder và waiter nào?'],
      141:['Long transaction giữ vacuum horizon như thế nào?','Routine VACUUM khác VACUUM FULL ở đâu?','Vì sao dead tuples và bloat không phải một chỉ số?'],
      142:['Write skew khác lost update thế nào?','PostgreSQL Repeatable Read còn serialization anomaly nào?','Chọn isolation theo invariant ra sao?'],
      143:['Synchronous replication có bảo đảm không mất dữ liệu tuyệt đối không?','Replication lag cần đo những vị trí LSN nào?','Vì sao failover cần fencing old primary?'],
      144:['Partitioning khác sharding ở failure boundary nào?','Partition key phải được chọn theo workload nào?','Vì sao shard sớm làm tăng scatter-gather và rebalance cost?']}
    for x in LESSONS:
        tests.extend({'query':q,'expected_note_id':x.note_id} for q in queries[x.number])
    data.update(version='1.0.28',updated_at='2026-10-01T20:00:00+07:00')
    data['note_registry']=registry; data['retrieval_test_set']=tests
    data['layers']['1_Nguon']['source_count']=len(data['source_registry'])
    data['layers']['2_Wiki']['note_count']=len(registry)
    expected=json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    if check:
        return [] if path.read_text()==expected else [str(path.relative_to(ROOT))]
    path.write_text(expected); return []

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--check',action='store_true'); args=ap.parse_args(); stale=[]
    PACK.mkdir(parents=True,exist_ok=True); WIKI.mkdir(parents=True,exist_ok=True)
    for x in LESSONS:
        k=normalize_markdown(deep_note(x)); n,a=curriculum(x,k)
        targets=((PACK/x.filename,k),(WIKI/(x.title+'.md'),k),(BASE/x.directory/'note.md',n),(BASE/x.directory/'after-note.md',a))
        for p,c in targets:
            if args.check:
                if not p.exists() or p.read_text()!=c: stale.append(str(p.relative_to(ROOT)))
            else: p.write_text(c)
    stale.extend(update_manifest(args.check))
    if stale: print('STALE\n'+'\n'.join(stale)); return 1
    print(('checked' if args.check else 'written')+f'={len(LESSONS)*4} stale=0'); return 0
if __name__=='__main__': raise SystemExit(main())
